#!/usr/bin/env node
/**
 * Downloads every photo in src/data/photos.ts into assets/photos/ and writes
 * src/data/photo-assets.generated.ts, so the app shows photos offline and does
 * not depend on the Pexels CDN. Run it on a machine with internet access before
 * an App Store build.
 *
 * Usage: npm run photos:bundle
 */
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.join(__dirname, '..');
const WIDTH = 1200;

async function main() {
  const source = fs.readFileSync(path.join(ROOT, 'src/data/photos.ts'), 'utf8');
  const photos = [...source.matchAll(/^\s+'([a-z0-9-]+)': \{ pexelsId: (\d+)/gm)].map((m) => ({ key: m[1], id: m[2] }));
  const outDir = path.join(ROOT, 'assets/photos');
  fs.mkdirSync(outDir, { recursive: true });

  const bundled = [];
  for (const { key, id } of photos) {
    const file = path.join(outDir, `${key}.jpg`);
    if (!fs.existsSync(file)) {
      const url = `https://images.pexels.com/photos/${id}/pexels-photo-${id}.jpeg?auto=compress&cs=tinysrgb&w=${WIDTH}`;
      const response = await fetch(url);
      if (!response.ok) {
        console.error(`❌ ${key}: HTTP ${response.status} (${url})`);
        continue;
      }
      fs.writeFileSync(file, Buffer.from(await response.arrayBuffer()));
      console.log(`✓ ${key}`);
    }
    bundled.push(key);
  }

  const lines = bundled.map((key) => `  '${key}': require('../../assets/photos/${key}.jpg'),`);
  fs.writeFileSync(
    path.join(ROOT, 'src/data/photo-assets.generated.ts'),
    `// This file is generated by \`npm run photos:bundle\`. Do not edit it by hand.\n` +
      `// While it is empty, photos load from the Pexels CDN.\n\n` +
      `/** Photo key → bundled asset (the number returned by require()). */\n` +
      `export const LOCAL_PHOTOS: Partial<Record<string, number>> = {\n${lines.join('\n')}\n};\n`,
  );
  console.log(`\n${bundled.length} af ${photos.length} fotos ligger nu i appen.`);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
